<?php declare(strict_types=1); ?>
<section class="section"><div class="container-wide"><div class="section-heading"><p class="eyebrow">Authorized administration</p><h1>Membership renewals</h1><p>Policies and overrides use separate permissions; every change is audited.</p></div><?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?>
<?php $grades=$configuration['grades']??[];$fees=$configuration['fees']??[];$policies=$configuration['policies']??[];if($canConfigure):?><details class="admin-panel"><summary>Create renewal policy</summary><form method="post" action="/admin/membership-renewal-policies" class="form-grid"><?= $csrf->field() ?><label>Name<input name="name" maxlength="180" required></label><label>Membership grade<select name="membership_grade" required><option value="">Select</option><?php foreach($grades as$g):?><option value="<?= $e($g['public_id']) ?>"><?= $e($g['name']) ?></option><?php endforeach;?></select></label><label>Renewal fee<select name="fee_setting" required><option value="">Select configured fee</option><?php foreach($fees as$f):?><option value="<?= $e($f['public_id']) ?>"><?= $e($f['name'].' · '.$f['currency'].' '.number_format(((int)$f['amount_minor'])/100,2)) ?></option><?php endforeach;?></select></label><label>Period value<input type="number" name="period_value" min="1" max="1200" required></label><label>Period unit<select name="period_unit"><option value="months">Months</option><option value="years">Years</option><option value="days">Days</option></select></label><label>Start rule<select name="start_rule"><option value="current_expiry">Extend current expiry</option><option value="payment_date">Start at verified payment date</option></select></label><label>Renewal window (days)<input type="number" name="renewal_window_days" min="0" max="3650" value="0" required></label><label>Grace period (days)<input type="number" name="grace_days" min="0" max="3650" value="0" required></label><label>Effective from<input type="date" name="effective_from" required></label><label>Effective until<input type="date" name="effective_until"></label><input type="hidden" name="active" value="1"><button class="btn btn-navy" type="submit">Save policy</button></form></details><div class="admin-panel"><h2>Configured policies</h2><?php if($policies===[]):?><p>No policy has been configured.</p><?php endif;?><?php foreach($policies as$p):?><p><strong><?= $e($p['name']) ?></strong> · <?= $e($p['grade_name']) ?> · <?= $e($p['period_value'].' '.$p['period_unit']) ?> · <?= $e($p['fee_name']) ?></p><?php endforeach;?></div><?php endif;?>
<div class="admin-list"><?php if($renewals===[]):?><p>No renewal records are available.</p><?php endif;?><?php foreach($renewals as$r):?><article class="admin-panel"><div class="programme-card-top"><strong><?= $e($r['membership_number'].' · '.$r['renewal_reference']) ?></strong><span class="status-pill"><?= $e(ucwords(str_replace('_',' ',$r['status']))) ?></span></div><p>Invoice: <?= $e($r['invoice_number']??'Not generated') ?> · <?= $e($r['invoice_status']??'') ?></p><?php if($canOverride):?><form method="post" action="/admin/membership-renewals/<?= rawurlencode($r['public_id']) ?>/override" class="form-grid"><?= $csrf->field() ?><label>Override action<select name="action" required><option value="">Select</option><option value="renew">Renew membership</option><option value="expire">Mark expired</option></select></label><label class="field-wide">Reason<textarea name="reason" minlength="10" maxlength="500" required></textarea></label><button class="btn btn-outline-navy" type="submit">Record override</button></form><?php endif;?></article><?php endforeach;?></div></div></section>
